function buildAdjListFromObj(adjObj) {
  const vertices = Object.keys(adjObj);
  let totalEdges = 0, maxDegree = 0;
  for (const v of vertices) {
    const deg = adjObj[v].length;
    totalEdges += deg;
    maxDegree = Math.max(maxDegree, deg);
  }
  const edges = totalEdges / 2;
  const density = edges / (vertices.length * (vertices.length - 1) / 2);
  return { vertices: vertices.length, edges, maxDegree, density };
}

function isComplete(adjObj) {
  const verts = Object.keys(adjObj);
  const V = verts.length;
  for (const v of verts) {
    if (adjObj[v].length !== V - 1) return false;
  }
  return true;
}

function vertexDegrees(adjObj) {
  const result = {};
  for (const [v, neighbors] of Object.entries(adjObj)) result[v] = neighbors.length;
  return result;
}

