function buildAdjListImpl(edges, V, directed = false) {
  const adj = Array.from({length: V}, () => []);
  for (const [u, v] of edges) {
    adj[u].push(v);
    if (!directed) adj[v].push(u);
  }
  return adj;
}

function buildAdjMatrixImpl(edges, V, directed = false) {
  const matrix = Array.from({length: V}, () => new Array(V).fill(0));
  for (const [u, v] of edges) {
    matrix[u][v] = 1;
    if (!directed) matrix[v][u] = 1;
  }
  return matrix;
}

function hasEdge(adjList, adjMatrix, u, v) {
  return { list: adjList[u].includes(v), matrix: adjMatrix[u][v] === 1 };
}

function edgesAreEquivalent(edges, V) {
  const list = buildAdjListImpl(edges, V);
  const matrix = buildAdjMatrixImpl(edges, V);
  for (let u = 0; u < V; u++)
    for (let v = 0; v < V; v++) {
      const inList = list[u].includes(v);
      const inMatrix = matrix[u][v] === 1;
      if (inList !== inMatrix) return false;
    }
  return true;
}

