function dfsIterativeImpl(adj, start) {
  const visited = new Set(), stack = [start];
  while (stack.length) {
    const node = stack.pop();
    if (visited.has(node)) continue;
    visited.add(node);
    for (const nb of adj[node]) if (!visited.has(nb)) stack.push(nb);
  }
  return visited;
}

function countComponentsImpl(adj) {
  const visited = new Set(); let c = 0;
  for (let v = 0; v < adj.length; v++) {
    if (!visited.has(v)) { dfsRecursiveImpl(adj, v, visited); c++; }
  }
  return c;
}

function findAllPathsImpl(adj, src, dst) {
  const result = [];
  function dfs(node, path, visited) {
    if (node === dst) { result.push([...path]); return; }
    for (const nb of adj[node]) {
      if (!visited.has(nb)) {
        visited.add(nb); path.push(nb);
        dfs(nb, path, visited);
        path.pop(); visited.delete(nb);
      }
    }
  }
  dfs(src, [src], new Set([src]));
  return result;
}

