function bfsImpl(adj, start) {
  const dist = new Array(adj.length).fill(-1);
  const parent = new Array(adj.length).fill(-1);
  const queue = [start];
  dist[start] = 0;
  while (queue.length) {
    const node = queue.shift();
    for (const nb of adj[node]) {
      if (dist[nb] === -1) { dist[nb] = dist[node] + 1; parent[nb] = node; queue.push(nb); }
    }
  }
  return { dist, parent };
}

function shortestPathImpl(adj, src, dst) {
  const { dist, parent } = bfsImpl(adj, src);
  if (dist[dst] === -1) return null;
  const path = [];
  for (let curr = dst; curr !== -1; curr = parent[curr]) path.push(curr);
  return path.reverse();
}

function multiBFSImpl(adj, sources) {
  const dist = new Array(adj.length).fill(-1);
  const queue = [];
  for (const src of sources) { dist[src] = 0; queue.push(src); }
  while (queue.length) {
    const node = queue.shift();
    for (const nb of adj[node]) {
      if (dist[nb] === -1) { dist[nb] = dist[node] + 1; queue.push(nb); }
    }
  }
  return dist;
}

