class GraphNode {
  constructor(val, neighbors=[]) { this.val=val; this.neighbors=neighbors; }
}

function cloneGraphDFSImpl(node) {
  if (!node) return null;
  const cloneMap = new Map();
  function dfs(curr) {
    if (cloneMap.has(curr)) return cloneMap.get(curr);
    const clone = new GraphNode(curr.val);
    cloneMap.set(curr, clone);
    for (const nb of curr.neighbors) clone.neighbors.push(dfs(nb));
    return clone;
  }
  return dfs(node);
}

function cloneGraphBFSImpl(node) {
  if (!node) return null;
  const cloneMap = new Map([[node, new GraphNode(node.val)]]);
  const queue = [node];
  while (queue.length) {
    const curr = queue.shift();
    for (const nb of curr.neighbors) {
      if (!cloneMap.has(nb)) { cloneMap.set(nb, new GraphNode(nb.val)); queue.push(nb); }
      cloneMap.get(curr).neighbors.push(cloneMap.get(nb));
    }
  }
  return cloneMap.get(node);
}

function isDeepCopy(original, clone) {
  if (!original && !clone) return true;
  if (!original || !clone) return false;
  const visited = new Map();
  function check(orig, cln) {
    if (visited.has(orig)) return visited.get(orig) === cln;
    if (orig === cln) return false;
    if (orig.val !== cln.val) return false;
    if (orig.neighbors.length !== cln.neighbors.length) return false;
    visited.set(orig, cln);
    return orig.neighbors.every((nb, i) => check(nb, cln.neighbors[i]));
  }
  return check(original, clone);
}

