function pacificAtlanticImpl(heights) {
  const m = heights.length, n = heights[0].length;
  const DIRS = [[1,0],[-1,0],[0,1],[0,-1]];
  function bfsFromBorder(starts) {
    const visited = new Set(starts.map(([r,c]) => r*n+c));
    const queue = [...starts];
    while (queue.length) {
      const [r,c] = queue.shift();
      for (const [dr,dc] of DIRS) {
        const nr=r+dr, nc=c+dc, key=nr*n+nc;
        if (nr>=0&&nr<m&&nc>=0&&nc<n&&!visited.has(key)&&heights[nr][nc]>=heights[r][c]) {
          visited.add(key); queue.push([nr,nc]);
        }
      }
    }
    return visited;
  }
  const ps=[], as=[];
  for (let r=0;r<m;r++){ps.push([r,0]);as.push([r,n-1]);}
  for (let c=1;c<n;c++) ps.push([0,c]);
  for (let c=0;c<n-1;c++) as.push([m-1,c]);
  const pac=bfsFromBorder(ps), atl=bfsFromBorder(as);
  const result=[];
  for (let r=0;r<m;r++) for (let c=0;c<n;c++) if (pac.has(r*n+c)&&atl.has(r*n+c)) result.push([r,c]);
  return result;
}

