function hasCycleDirectedImpl(adj) {
  const V = adj.length;
  const color = new Array(V).fill(0);
  function dfs(u) {
    color[u] = 1;
    for (const v of adj[u]) {
      if (color[v] === 1) return true;
      if (color[v] === 0 && dfs(v)) return true;
    }
    color[u] = 2;
    return false;
  }
  for (let u = 0; u < V; u++) if (color[u] === 0 && dfs(u)) return true;
  return false;
}

function hasCycleUndirectedImpl(adj) {
  const visited = new Set();
  function dfs(u, parent) {
    visited.add(u);
    for (const v of adj[u]) {
      if (!visited.has(v)) { if (dfs(v, u)) return true; }
      else if (v !== parent) return true;
    }
    return false;
  }
  for (let u = 0; u < adj.length; u++) if (!visited.has(u) && dfs(u, -1)) return true;
  return false;
}

function canFinishImpl(numCourses, prerequisites) {
  const adj = Array.from({length: numCourses}, () => []);
  for (const [course, prereq] of prerequisites) adj[prereq].push(course);
  return !hasCycleDirectedImpl(adj);
}

